var e=[{title:`Hlavní složky`,text:`Síla je schopnost vyvinout sílu a výbušnost je síla vyvinutá rychle. Svalová vytrvalost znamená opakovat nebo držet svalové stahy. Kardiorespirační vytrvalost podporuje delší výkony a závisí na srdci, plicích, oběhu a svalech. Mobilita je schopnost aktivně se pohybovat v užitečných rozsazích, zatímco pohyblivost popisuje, jak daleko se tkáň nebo kloub při protažení dostane. Rovnováha a koordinace vám pomáhají ovládat pohyb.`},{title:`Složení těla`,text:`Poměr svalů, tuku, kostí a dalších tkání může být důležitý pro zdraví nebo sport, ale kondici plně nepopisuje. Dva lidé s podobnou hmotností se mohou hodně lišit v síle, kardiovaskulární kapacitě nebo pohybových dovednostech. Vzhled nenahradí zkoušku toho, co opravdu zvládnete.`},{title:`Jak se složky ovlivňují`,text:`Dřep vyžaduje sílu nohou a trupu, dostatek mobility pro zvolenou hloubku a koordinaci, abyste zátěž udrželi pod kontrolou. Túra víc využívá aerobní a svalovou vytrvalost, i když pomáhá i síla a rovnováha. Zlepšení jedné vlastnosti může pomoci jiné, ale nerozvine všechny stejně.`},{title:`Trénink podle cíle`,text:`Týden zaměřený na celkovou kondici může zahrnovat dva celotělové odporové tréninky, mírnou chůzi nebo jízdu na kole a krátké cvičení rovnováhy nebo mobility. Důraz na sílu využívá odporové cviky, které se časem ztěžují, s dostatkem odpočinku mezi výkony. Důraz na vytrvalost tráví víc času nepřetržitým pohybem a intervaly a zachovává trochu silové práce.`},{title:`Používání TrainUp`,text:`V Profilu zvolte hlavní cíl a dál dělejte nějakou práci i pro ostatní vlastnosti. Pokrok měřte tím, co se ke každé hodí: opakování nebo zátěží pro sílu, tempem a dechem pro vytrvalost, kontrolovaným rozsahem pro mobilitu. Trénink neposuzujte podle toho, kolik jste se zapotili nebo kolik kalorií jste spálili.`}];var a=[{label:`HHS: pojmy tělesné kondice`,url:`https://www.cdc.gov/physical-activity-basics/about/index.html`},{label:`Stanovisko ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Doporučení WHO`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var n={sections:e,sources:a};export{n as default,e as sections,a as sources};